    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        List<String> tokens = new ArrayList<>();
        while (st.hasMoreTokens()) tokens.add(st.nextToken());
        Node root = new Node(Integer.parseInt(tokens.get(0)));
        int count = 1;
        ArrayDeque<Node> q = new ArrayDeque<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < tokens.size()) {
            Node node = q.poll();
            if (i < tokens.size()) {
                if (!tokens.get(i).equals("null")) {
                    node.left = new Node(Integer.parseInt(tokens.get(i)));
                    q.add(node.left);
                    count++;
                }
                i++;
            }
            if (i < tokens.size()) {
                if (!tokens.get(i).equals("null")) {
                    node.right = new Node(Integer.parseInt(tokens.get(i)));
                    q.add(node.right);
                    count++;
                }
                i++;
            }
        }
        Node head = treeToDll(root);
        StringBuilder fwd = new StringBuilder(), bwd = new StringBuilder();
        Node tail = null;
        int c = 0;
        for (Node cur = head; cur != null && c < count; cur = cur.right, c++) {
            if (c > 0) fwd.append(' ');
            fwd.append(cur.val);
            tail = cur;
        }
        c = 0;
        for (Node cur = tail; cur != null && c < count; cur = cur.left, c++) {
            if (c > 0) bwd.append(' ');
            bwd.append(cur.val);
        }
        System.out.println(fwd);
        System.out.println(bwd);
    }
}
